) ON COMMIT DROP;
CREATE TEMP TABLE stage_links (qid text, term_slug text, relevance real, is_primary boolean) ON COMMIT DROP;
CREATE TEMP TABLE stage_tags (qid text, tag_slug text) ON COMMIT DROP;

INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q233657', 'Second Matabele War', 'The First Chimurenga, also known as the Second Matabele War, was fought between 1896 and 1897 in the region that later became Southern Rhodesia (now Zimbabwe). The conflict was initially between the British South Africa Company (BSAC) and the Matabele people, later expanding to include the Shona people in the rest of Southern Rhodesia.', 1896, 3, NULL, 1897, 10, NULL, 'month', 'March 1896 – October 1897', 57, 'https://en.wikipedia.org/wiki/First_Chimurenga'),
